#!/usr/bin/env python3
"""Writes lib/core/models/catalog_data.dart from the release's manifest.json.

  gen_catalog.py manifest.json > lib/core/models/catalog_data.dart
"""

import json
import sys


def main():
    m = json.load(open(sys.argv[1]))
    out = [
        "// GENERATED by tool/models/gen_catalog.py from the narrator-models manifest.json.",
        "// Do not edit by hand; rerun the generator after the models workflow republishes.",
        "",
        "import 'catalog.dart';",
        "",
        "const packFileData = <String, List<PackFile>>{",
    ]
    for pack, info in m["packs"].items():
        out.append(f"  '{pack}': [")
        for f in info["files"]:
            unzip = ", unzip: true" if f["unzip"] else ""
            out.append(f"    PackFile('{f['asset']}', '{f['path']}', {f['size']}, '{f['sha256']}'{unzip}),")
        out.append("  ],")
    out.append("};")
    print("\n".join(out))


if __name__ == "__main__":
    main()
